@page "/"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>RecipeShare — Home</PageTitle>

<div class="container">
    <div class="text-center my-5">
        <h1 class="display-4">🍳 RecipeShare</h1>
        <p class="lead text-muted">Discover and share delicious recipes from around the world.</p>
    </div>

    <h2 class="mb-4">Browse by Category</h2>
    <div class="row row-cols-1 row-cols-sm-2 row-cols-md-3 g-4">
        @foreach (var category in RecipeService.Categories)
        {
            <div class="col">
                <a href="category/@Uri.EscapeDataString(category)" class="text-decoration-none">
                    <div class="card h-100 shadow-sm border-0">
                        <div class="card-body text-center py-5">
                            <h3 class="card-title">@GetCategoryEmoji(category) @category</h3>
                            <p class="card-text text-muted">
                                @RecipeService.GetByCategory(category).Count recipe(s)
                            </p>
                        </div>
                    </div>
                </a>
            </div>
        }
    </div>

    <div class="text-center mt-5">
        <a href="submit" class="btn btn-success btn-lg">📝 Submit Your Recipe</a>
    </div>
</div>

@code {
    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Thai" => "🍜",
        "Mexican" => "🌮",
        "Japanese" => "🍱",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}

@page "/category/{CategoryName}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes — RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1 class="mb-4">@CategoryName Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes found in this category.</div>
    }
    else
    {
        <div class="row row-cols-1 row-cols-md-2 g-4">
            @foreach (var recipe in Recipes)
            {
                <div class="col">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">
                                <a href="recipe/@recipe.Id" class="text-decoration-none">@recipe.Title</a>
                            </h5>
                            <p class="card-text text-muted">@recipe.Description</p>
                            <div class="d-flex justify-content-between align-items-center">
                                <span class="text-warning">
                                    @for (int i = 1; i <= 5; i++)
                                    {
                                        @(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")
                                    }
                                </span>
                                <small class="text-muted">@recipe.TotalRatings rating(s)</small>
                            </div>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private IReadOnlyList<Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetByCategory(Uri.UnescapeDataString(CategoryName));
    }
}

@page "/recipe/{Id:int}"
@using RecipeShare.Models
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") — RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (Recipe is not null)
            {
                <li class="breadcrumb-item">
                    <a href="category/@Uri.EscapeDataString(Recipe.Category)">@Recipe.Category</a>
                </li>
                <li class="breadcrumb-item active">@Recipe.Title</li>
            }
        </ol>
    </nav>

    @if (Recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <h1>@Recipe.Title</h1>
        <p class="lead text-muted">@Recipe.Description</p>

        <div class="row mt-4">
            <div class="col-md-4">
                <div class="card mb-4">
                    <div class="card-header"><strong>Ingredients</strong></div>
                    <ul class="list-group list-group-flush">
                        @foreach (var ingredient in Recipe.Ingredients)
                        {
                            <li class="list-group-item">@ingredient</li>
                        }
                    </ul>
                </div>
            </div>

            <div class="col-md-8">
                <h4>Steps</h4>
                <ol class="list-group list-group-numbered mb-4">
                    @foreach (var step in Recipe.Steps)
                    {
                        <li class="list-group-item">@step</li>
                    }
                </ol>
            </div>
        </div>

        <div class="card mt-2 mb-4">
            <div class="card-body">
                <h5 class="card-title">Rate this Recipe</h5>
                <p class="text-muted mb-2">
                    Average: @Recipe.AverageRating.ToString("F1") / 5
                    (@Recipe.TotalRatings ratings)
                </p>
                <StarRating RecipeId="Recipe.Id" />
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetById(Id);
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="d-flex align-items-center gap-2">
    <div style="font-size: 1.8rem; cursor: pointer; user-select: none;">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span
                @onmouseover="() => hoverStar = star"
                @onmouseout="() => hoverStar = 0"
                @onclick="() => SubmitRating(star)"
                class="@(i <= DisplayStars ? "text-warning" : "text-secondary")">
                @(i <= DisplayStars ? "★" : "☆")
            </span>
        }
    </div>

    @if (submitted)
    {
        <span class="badge bg-success">Thanks! You rated @selectedStar star(s).</span>
    }
</div>

@code {
    [Parameter, EditorRequired] public int RecipeId { get; set; }

    private int hoverStar;
    private int selectedStar;
    private bool submitted;

    private int DisplayStars => hoverStar > 0 ? hoverStar : selectedStar;

    private void SubmitRating(int star)
    {
        selectedStar = star;
        RecipeService.AddRating(RecipeId, star);
        submitted = true;
    }
}

