toolArgs.new_str:
@page "/"
@using RecipeShare.Services
@inject RecipeService RecipeService

<PageTitle>RecipeShare — Home</PageTitle>

<div class="container">
    <div class="text-center my-5">
        <h1 class="display-4">🍳 RecipeShare</h1>
        <p class="lead text-muted">Discover and share delicious recipes from around the world.</p>
    </div>

    <h2 class="mb-4">Browse by Category</h2>
    <div class="row row-cols-1 row-cols-sm-2 row-cols-md-3 g-4">
        @foreach (var category in RecipeService.Categories)
        {
            <div class="col">
                <a href="category/@Uri.EscapeDataString(category)" class="text-decoration-none">
                    <div class="card h-100 shadow-sm border-0">
                        <div class="card-body text-center py-5">
                            <h3 class="card-title">@GetCategoryEmoji(category) @category</h3>
                            <p class="card-text text-muted">
                                @RecipeService.GetByCategory(category).Count recipe(s)
                            </p>
                        </div>
                    </div>
                </a>
            </div>
        }
    </div>

    <div class="text-center mt-5">
        <a href="submit" class="btn btn-success btn-lg">📝 Submit Your Recipe</a>
    </div>
</div>

@code {
    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Thai" => "🍜",
        "Mexican" => "🌮",
        "Japanese" => "🍱",
        "Desserts" => "🍰",
        _ => "🍽️"
    };
}
